public interface Pagavel {
    public double valor();
}

Boleto:
public class Boleto implements Pagavel {
    public String codigo;
    public double valorBase;

    public Boleto(String codigo, double valorBase) {
        this.codigo = codigo;
        this.valorBase = valorBase;
    }

    public double valor() {
        return valorBase;
    }
}

